func (h *Handler) GetBalance(ctx context.Context, req BalanceRequest) (*Balance, error) {
	caller, err := auth.CallerFrom(ctx)
	if err != nil {
		return nil, err
	}
	acct, err := h.store.Account(ctx, req.AccountID)
	if err != nil {
		return nil, err
	}
	if acct.OwnerID != caller.UserID {
		return nil, ErrForbidden
	}
	return h.store.Balance(ctx, acct.ID)
}

